#!/usr/bin/env python3
"""Generate the selfhost Ark source embedding the WASI P2 runtime core bridge."""
from __future__ import annotations

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_WASM = ROOT / "runtime/wasi-p2-bridge/target/wasm32-unknown-unknown/release/arukellt_wasi_p2_bridge.wasm"
OUT = ROOT / "src/compiler/wasm/component_p2_runtime_bridge_generated.ark"


def render(data: bytes) -> str:
    hex_text = data.hex()
    chunks = [hex_text[i : i + 120] for i in range(0, len(hex_text), 120)]
    lines = [
        "// @generated by scripts/gen/generate-wasi-runtime-bridge.py; do not edit.",
        "",
        "fn p2_runtime_bridge_module_bytes() -> Vec<i32> {",
        f'    let mut hex = "{chunks[0] if chunks else ""}"',
    ]
    for chunk in chunks[1:]:
        lines.append(f'    hex = concat(hex, "{chunk}")')
    lines += [
        "    p2_runtime_bridge_hex_to_bytes(hex)",
        "}",
        "",
        "fn p2_runtime_bridge_hex_to_bytes(hex: String) -> Vec<i32> {",
        "    let out = Vec::new<i32>()",
        "    let mut i = 0",
        "    while i + 1 < len(hex) {",
        "        let hi = p2_runtime_bridge_hex_val(char_at(hex, i))",
        "        let lo = p2_runtime_bridge_hex_val(char_at(hex, i + 1))",
        "        push(out, hi * 16 + lo)",
        "        i = i + 2",
        "    }",
        "    out",
        "}",
        "",
        "fn p2_runtime_bridge_hex_val(c: i32) -> i32 {",
        "    if c >= 48 && c <= 57 { return c - 48 }",
        "    if c >= 97 && c <= 102 { return c - 87 }",
        "    0",
        "}",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--wasm", type=Path, default=DEFAULT_WASM)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = render(args.wasm.read_bytes())
    if args.check:
        return 0 if OUT.exists() and OUT.read_text(encoding="utf-8") == generated else 1
    OUT.write_text(generated, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
